442	func deleteMemoSharesTx(ctx context.Context, tx *sql.Tx, userID int32, memoIDs []int32) error {
443		if _, err := tx.ExecContext(ctx, `DELETE FROM memo_share WHERE creator_id = `+deleteUserPlaceholder(1), userID); err != nil {
444			return err
445		}
446		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
447			clause, args := deleteUserInClause(1, batch)
448			if _, err := tx.ExecContext(ctx, `DELETE FROM memo_share WHERE memo_id IN `+clause, args...); err != nil {
449				return err
450			}
451		}
452		return nil
453	}
454	
455	func deleteInboxesByIDsTx(ctx context.Context, tx *sql.Tx, inboxIDs []int32) error {
456		for _, batch := range deleteUserBatches(inboxIDs, deleteUserBatchSize) {
457			clause, args := deleteUserInClause(1, batch)
458			if _, err := tx.ExecContext(ctx, `DELETE FROM inbox WHERE id IN `+clause, args...); err != nil {
459				return err
460			}
461		}
