463	}
464	
465	func deleteUserIdentitiesTx(ctx context.Context, tx *sql.Tx, userID int32) error {
466		_, err := tx.ExecContext(ctx, `DELETE FROM user_identity WHERE user_id = `+deleteUserPlaceholder(1), userID)
467		return err
468	}
469	
470	func deleteUserSettingsTx(ctx context.Context, tx *sql.Tx, userID int32) error {
471		_, err := tx.ExecContext(ctx, "DELETE FROM `user_setting` WHERE user_id = "+deleteUserPlaceholder(1), userID)
472		return err
473	}
474	
475	func deleteMemoRelationsTx(ctx context.Context, tx *sql.Tx, memoIDs []int32) error {
476		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
477			memoClause, args := deleteUserInClause(1, batch)
478			relatedClause, relatedArgs := deleteUserInClause(len(args)+1, batch)
479			query := `DELETE FROM memo_relation WHERE memo_id IN ` + memoClause + ` OR related_memo_id IN ` + relatedClause
480			args = append(args, relatedArgs...)
481			if _, err := tx.ExecContext(ctx, query, args...); err != nil {
482				return err
483			}
484		}
485		return nil
